on_light_create.expression:
v.index = 1 + v.index;
v.amount_of_particle = 12;
v.square_size = 4;

v.particles_per_side = v.amount_of_particle / 4;
v.step = v.square_size / (v.particles_per_side + 1);

v.side = math.floor(v.index / v.particles_per_side);
v.position_on_side = math.mod(v.index, v.particles_per_side) + 1;

v.x_position = (-v.square_size / 2 + v.step * v.position_on_side) * (v.side == 0)
             + (v.square_size / 2) * (v.side == 1)
             + (v.square_size / 2 - v.step * v.position_on_side) * (v.side == 2)
             + (-v.square_size / 2) * (v.side == 3);

v.y_position = (v.square_size / 2) * (v.side == 0)
             + (v.square_size / 2 - v.step * v.position_on_side) * (v.side == 1)
             + (-v.square_size / 2) * (v.side == 2)
             + (-v.square_size / 2 + v.step * v.position_on_side) * (v.side == 3);

v.x_direction = 0;
v.y_direction = 1;
v.z_direction = 0;
